const thresholdMinutes = 60;
const cutoff = Date.now() - thresholdMinutes * 60_000;
const response = $input.first()?.json ?? {};
const items = Array.isArray(response.items) ? response.items : [];
const reminders = items.filter((item) => {
  const createdAt = Date.parse(item.created_at ?? '');
  return item.is_current === true && item.is_actionable === true && Number.isFinite(createdAt) && createdAt <= cutoff;
});
return reminders.map((item) => ({ json: { notification: `Aging review reminder: ${item.review_case_id}`, review_case: item, processed_limit: 100, truncated: Number(response.total ?? 0) > items.length } }));
